```ts
interface RouteStrategy {
  computeRoute(from: Point, to: Point): Route;
}

class FastestRoute implements RouteStrategy {
  computeRoute(from, to) { /* minimize travel time */ }
}
class AvoidTollsRoute implements RouteStrategy {
  computeRoute(from, to) { /* exclude toll edges */ }
}

class Navigator {
  constructor(private strategy: RouteStrategy) {}
  setStrategy(s: RouteStrategy) { this.strategy = s; }
  getDirections(from: Point, to: Point) {
    return this.strategy.computeRoute(from, to);
  }
}

const nav = new Navigator(new FastestRoute());
nav.getDirections(home, office);        // fastest path
nav.setStrategy(new AvoidTollsRoute());
nav.getDirections(home, office);        // same call, different algorithm
```

`getDirections()` never changes — only the object assigned to `strategy` does. Swap it with `setStrategy()` and the very next call runs different logic, with zero edits to `Navigator`. The same shape works for sort comparators, payment gateways, or compression codecs.
